function validate([arr1, arr2]) {
  if (!Array.isArray(arr1) || arr1.length < 1 || arr1.length > 1000) return 'arr1 needs 1 to 1000 values.';
  if (!Array.isArray(arr2) || arr2.length < 1 || arr2.length > 1000) return 'arr2 needs 1 to 1000 values.';
  if (arr1.concat(arr2).some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Values are whole numbers from 0 to 1000.';
  if (new Set(arr2).size !== arr2.length) return 'The values of arr2 must be distinct.';
  const present = new Set(arr1);
  if (arr2.some(v => !present.has(v))) return 'Every value of arr2 must occur in arr1.';
  return null;
}

