function relativeSortArray(arr1, arr2) {
  const rank = new Map();
  for (let i = 0; i < arr2.length; i++) {
    rank.set(arr2[i], i);
  }
  const keyOf = (value) => {
    if (rank.has(value)) {
      return rank.get(value);
    }
    return arr2.length + value;
  };
  return [...arr1].sort((a, b) => keyOf(a) - keyOf(b));
}

