function relativeSortArray(arr1, arr2) {
  const result = [];
  for (const wanted of arr2) {
    for (const value of arr1) if (value === wanted) result.push(value);
  }
  const rest = arr1.filter(value => !arr2.includes(value));
  for (let i = 1; i < rest.length; i++) {
    for (let j = i; j > 0 && rest[j - 1] > rest[j]; j--) [rest[j - 1], rest[j]] = [rest[j], rest[j - 1]];
  }
  return result.concat(rest);
}

