function generate(rand, size) {
  const large = size === 'large';
  const top = large ? 1000 : (rand() < 0.5 ? 6 : 1000);
  const pick = () => Math.floor(rand() * (top + 1));
  const length2 = large ? 1 + Math.floor(rand() * 400) : 1 + Math.floor(rand() * 4);
  const chosen = new Set();
  while (chosen.size < length2) chosen.add(pick());
  const arr2 = [...chosen];
  const arr1 = [...arr2];
  const length1 = large ? 1000 : Math.min(12, arr2.length + Math.floor(rand() * 7));
  const extraShare = rand();
  while (arr1.length < length1) {
    arr1.push(rand() < extraShare ? pick() : arr2[Math.floor(rand() * arr2.length)]);
  }
  for (let i = arr1.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr1[i], arr1[j]] = [arr1[j], arr1[i]];
  }
  return [arr1, arr2];
}
